export const FIRST_ENTRY_MS = 30 * 60 * 1000;
export const ROUND_MS = 24 * 60 * 60 * 1000;
export const NEXT_ENTRY_MS = 60 * 60 * 1000;

// activatedAt is written once to the server database, never generated by a browser.
export function scheduleAt(activatedAt, now) {
  if (activatedAt === null) return { phase: 'prelaunch', current: null, next: null, registration: null };
  if (!Number.isSafeInteger(activatedAt) || !Number.isSafeInteger(now)) throw Error('Invalid schedule time');
  const firstStart = activatedAt + FIRST_ENTRY_MS;
  if (now < firstStart) {
    return {
      phase: 'registration', current: null,
      next: { id: 1, start: firstStart, end: firstStart + ROUND_MS },
      registration: { roundId: 1, opensAt: activatedAt, closesAt: firstStart, open: now >= activatedAt },
    };
  }
  const index = Math.floor((now - firstStart) / ROUND_MS);
  const start = firstStart + index * ROUND_MS, end = start + ROUND_MS;
  return {
    phase: 'live', current: { id: index + 1, start, end },
    next: { id: index + 2, start: end, end: end + ROUND_MS },
    registration: { roundId: index + 2, opensAt: end - NEXT_ENTRY_MS, closesAt: end, open: now >= end - NEXT_ENTRY_MS && now < end },
  };
}

export function countdown(ms) {
  const seconds = Math.max(0, Math.ceil(ms / 1000));
  return [Math.floor(seconds / 3600), Math.floor(seconds / 60) % 60, seconds % 60].map(n => String(n).padStart(2, '0')).join(':');
}
